const bggId = $('Webhook - POST confirm').first().json.body.bggId;
const xml = items[0].json.data || items[0].json;
const text = typeof xml === 'string' ? xml : JSON.stringify(xml);

function attr(tagRe) { const m = text.match(tagRe); return m ? m[1] : ''; }
function decode(s) {
  return s.replace(/&amp;/g, '&').replace(/&lt;/g, '<').replace(/&gt;/g, '>').replace(/&quot;/g, '"').replace(/&#10;/g, ' ').replace(/&#13;/g, ' ').replace(/<[^>]+>/g, ' ').replace(/\s+/g, ' ').trim();
}

const title = attr(/<name[^>]*type="primary"[^>]*value="([^"]*)"/) || attr(/<name[^>]*value="([^"]*)"/);
const yearpublished = attr(/<yearpublished[^>]*value="([^"]*)"/);
const thumbMatch = text.match(/<thumbnail>([^<]*)<\/thumbnail>/);
const thumbnail = thumbMatch ? thumbMatch[1] : null;
const descMatch = text.match(/<description>([\s\S]*?)<\/description>/);
const desc = descMatch ? decode(descMatch[1]).slice(0, 260) : '';
const ratingMatch = text.match(/<ratings>[\s\S]*?<average[^>]*value="([^"]*)"/);
const bggRating = ratingMatch ? Number(ratingMatch[1]) : null;

const categories = [];
const catRe = /<link[^>]*type="boardgamecategory"[^>]*value="([^"]*)"/g;
let cm;
while ((cm = catRe.exec(text)) && categories.length < 2) categories.push(cm[1]);

const mechanics = [];
const mechRe = /<link[^>]*type="boardgamemechanic"[^>]*value="([^"]*)"/g;
let mm;
while ((mm = mechRe.exec(text)) && mechanics.length < 2) mechanics.push(mm[1]);

const expansions = [];
const expRe = /<link[^>]*type="boardgameexpansion"[^>]*value="([^"]*)"[^>]*inbound="true"[^>]*\/>/g;
let em;
while ((em = expRe.exec(text))) expansions.push(em[1]);

const now = new Date().toISOString();

return [{ json: {
  game_id: 'bgg-' + bggId,
  bgg_id: Number(bggId),
  title: title || ('BGG #' + bggId),
  genre: categories.join(' / '),
  type: mechanics.join(' / '),
  desc,
  expansions: JSON.stringify(expansions),
  desire_to_play: 0,
  thinning_candidate: false,
  bgg_rating: bggRating,
  photo_url: thumbnail,
  added_at: now,
  updated_at: now
} }];

const r = items[0].json;
let expansions = [];
try { expansions = r.expansions ? JSON.parse(r.expansions) : []; } catch (e) {}
return [{ json: {
  id: r.game_id,
  bggId: r.bgg_id,
  title: r.title,
  genre: r.genre,
  type: r.type,
  desc: r.desc,
  expansions,
  desireToPlay: r.desire_to_play || 0,
  thinningCandidate: !!r.thinning_candidate,
  bggRating: r.bgg_rating,
  photoUrl: r.photo_url
} }];
